import{_ as o,l,o as e,c as s,v as r,p as n,x as t,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"固件安全","description":"","frontmatter":{"title":"固件安全","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/firmware-security.md","filePath":"cs/firmware-security.md","lastUpdated":1789023840000}'),p={name:"cs/firmware-security.md"};function B(E,a,_,u,m,f){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="固件安全" tabindex="-1">固件安全 <a class="header-anchor" href="#固件安全" aria-label="Permalink to &quot;固件安全&quot;">​</a></h1><div class="epigraph"><p>固件先于操作系统，更新通道常弱：无签名、无回滚保护、管理引擎不透明。固件完整是 TCB 的底，补丁窗口与供应链在此最痛。</p><footer>—— 据 NIST SP 800-193；UEFI 对胶囊更新的讨论；对照 Intel 管理引擎的公开分析点名</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/secure-boot-chain">安全启动</a>假定固件是锚的一部分。缺口是<strong>固件自己的更新与植入</strong>。本课讲签名更新、防回滚、带外管理，不写刷入恶意固件的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BIOS 密码空、更新不验签、回滚到易受版本。缺口是：签名、版本单调、带外管理面与主机隔离。</p><h3 id="供应" tabindex="-1">供应 <a class="header-anchor" href="#供应" aria-label="Permalink to &quot;供应&quot;">​</a></h3><p>出厂植入不在 OS 扫描器视野。SBOM 对固件更弱。</p><p><span class="marginnote">SP 800-193 平台固件弹性。禁止固件植入教程。功耗分析下一课换物理侧信道。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照主机补丁与固件补丁周期。管理网分段。下一课 DPA。</p>',12)),(e(),n(h,null,{default:t(()=>[c(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22%E5%9B%BA%E4%BB%B6%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20SIG%5B%22%E5%BF%85%E9%A1%BB%E9%AA%8C%E7%AD%BE%22%5D%0A%20%20UPD%20--%3E%20RB%5B%22%E9%98%B2%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20OOB%5B%22%E5%B8%A6%E5%A4%96%E7%AE%A1%E7%90%86%22%5D%20--%3E%20SEG%5B%22%E4%B8%8E%E7%94%9F%E4%BA%A7%E7%BD%91%E5%88%86%E6%AE%B5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TCB 含固件。物理攻击下一课假设盒子在手。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写刷机攻击。功耗分析 DPA 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>启动链含固件；固件更新必须验签。</li><li>防回滚与带外面是合同。</li><li>OS 扫描看不见出厂植入。</li><li>下一课功耗分析。</li><li>出处：NIST SP 800-193；UEFI；Anderson。</li></ul>',8))])}const P=o(p,[["render",B]]);export{S as __pageData,P as default};
